        end;
        nlb:addAll(s, nil, _enemyDeck and _enemyDeck.listnam or "", _enemySelectedCards and _enemySelectedCards.listnam or "", false);
        if _enemyDeck then
            nlb:shuffle(_enemyDeck.listnam);
        end;
end;
    end,
};

