            return 'images/sabotage/sabot17.jpg';
        end
    end,
    var { time = 0; wastext = false; lasttext = nil; tag = ''; autowired = false; },
    dsc = function(s)
        p("Капитан Ридли выглядел растерянным – Я, конечно, мог запросить информацию в Справочной системе, но это мог сделать и любой другой офицер – Внезапно Ридли воспрял духом и его глаза заблестели – Я знаю как доказать свою непричастность к этому происшествию! Вы можете обратиться в отдел Связи на нашем корабле. Дежурный в отделе может посмотреть программу и проверить, кто за последние дни делал запросы в Справочной системе касательно работы криогенных систем – Ридли облегченно выдохнул и расслабленно откинулся в своем кресле – Я не делал никаких запросов ни пять дней назад, ни месяц.^"..
"Ну что ж нужно будет проверить эту версию. Заодно проверить, может кто-то другой делал запрос в Справочной системе.");
    end,
    way = {
        'v_f90ea85c_5acf_48f1_bec3_7849d728ad24',
    },
    xdsc = function(s)
        p(nlb:alts_txt(s));
    end,
    wcns = {
        ['v_f90ea85c_5acf_48f1_bec3_7849d728ad24'] = function() return (_sabotage_cnt ~= nil) and (_sabotage_cnt == 1); end,
    },
    alts = {
    },
    autos = function(s)
        update_action_count();
        nlb:revive();
        nlb:ways_chk(s);
        if ((_isCardDsc)) then     _vl_165d6bd7_5634_426f_a0a6_1c3efb410023_da359c81_cbcf_420f_b683_d0b05e18c8b5 =  true ;
        nlb:nlbwalk(v_da359c81_cbcf_420f_b683_d0b05e18c8b5, v_165d6bd7_5634_426f_a0a6_1c3efb410023, true); 
        return false;
 end;
        vn:standard_renew();
        return true;
    end,
    nextsnd = function(s)
        local sndfile = nlb:pop('v_da359c81_cbcf_420f_b683_d0b05e18c8b5_snds');
        if sndfile ~= nil then
            s.sndout(s);
            add_sound(sndfile);
        end;
    end,
    theme_file = function(s)
        return 'theme_standard.lua';
    end,
    enter = function(s, f)
        nlb:theme_switch(s:theme_file());
        s.lasttext = nil;
        s.wastext = false;
        if not (f.autowired) then
        end;
        s:initf();
    end,
    initf = function(s)
        s.snd(s);
        local bg_img = s.bgimg(s);
        nlb:revive();
        nlb:ways_chk(s);
        vn:scene(bg_img);
        local geomFuncNeedToCall = true;
        if geomFuncNeedToCall then
            vn:auto_geom('dissolve', function() s.autos(s); end);
